package com.portfolio.controller;
import com.portfolio.model.Blog; import com.portfolio.repository.BlogRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/blogs") public class BlogController { private final BlogRepository repo; public BlogController(BlogRepository r){repo=r;} @GetMapping public List<Blog> all(){return repo.findAllByOrderByDisplayOrderAsc();} @GetMapping("/{id}") public ResponseEntity<Blog> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public Blog create(@RequestBody Blog x){return repo.save(x);} @PutMapping("/{id}") public ResponseEntity<Blog> update(@PathVariable Long id,@RequestBody Blog p){return repo.findById(id).map(x->{
x.setTitle(p.getTitle());x.setSlug(p.getSlug());x.setExcerpt(p.getExcerpt());x.setContent(p.getContent());x.setImage(p.getImage());x.setPublished(p.getPublished());x.setDisplayOrder(p.getDisplayOrder());return ResponseEntity.ok(repo.save(x));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }